#include <stdint.h>
#include "led.h"
#include "uart.h"
#include "timebase.h"

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif

int main(void)
{
	led_init();
	uart_tx_init();
	timebase_init();

	while(1) {
		led_on();
		delay(100);
		led_off();
		delay(100);
//		printf("Hello World!\r\n");
	}
    /* Loop forever */
	for(;;);
}
